UPDATE `planting_batch`
plot_id = #{plotId}, crop_id = #{cropId}, user_id = #{userId}, batch_no = #{batchNo}, planting_area = #{plantingArea}, area_unit = #{areaUnit}, planted_at = #{plantedAt}, expected_harvest_at = #{expectedHarvestAt}, actual_harvest_at = #{actualHarvestAt}, harvester = #{harvester}, growth_stage_id = #{growthStageId}, expected_yield_amount = #{expectedYieldAmount}, grown_days = #{grownDays}, crop_image = #{cropImage}, status = #{status}, yield_amount = #{yieldAmount}, yield_unit = #{yieldUnit}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT 
FROM `planting_batch` pb



        AND pb.plot_id = #{plotId}


        AND pb.crop_id = #{cropId}


        AND pb.user_id = #{userId}


        AND CONCAT('Batch_', LPAD(CAST(pb.id AS CHAR),
            GREATEST(3, CHAR_LENGTH(CAST(pb.id AS CHAR))), '0')) LIKE CONCAT('%', #{batchNo}, '%')


        AND pb.status = #{status}


ORDER BY pb.id DESC

SELECT COUNT(1)
FROM `planting_batch`
WHERE user_id = #{userId}
  AND batch_no = #{batchNo}

    AND id != #{excludeId}

SELECT COUNT(1)
FROM `planting_batch`
WHERE plot_id = #{plotId}
  AND status = 1

    AND id != #{excludeId}
